    LinkRaw &linkRaw = mac.GetInstance().GetLinkRaw();

    if (linkRaw.IsEnabled())
    {
        linkRaw.InvokeReceiveDone(aFrame, aError);
    }
    else
#endif
    {
        mac.HandleReceivedFrame(aFrame, aError);
    }
}

